const repositoryRoot = resolve(dirname(fileURLToPath(import.meta.url)), '../../..');
const implementations = Object.freeze({"dependencies":"#!/usr/bin/env node\n\n// 全仓依赖检查只读取受 Git 管理的 manifest、lockfile、工具链和 workflow；\n// 更新必须由人工明确执行并经过产品真实验收，CI/Release 不得自动改写依赖。\nimport { existsSync, readFileSync } from \"node:fs\";\nimport { spawnSync } from \"node:child_process\";\nimport { dirname, resolve } from \"node:path\";\nimport { fileURLToPath } from \"node:url\";\n\nconst repositoryRoot = process.env.GMB_REPOSITORY_ROOT || process.cwd();\nconst contractPath = resolve(repositoryRoot, \".github/dependencies.json\");\nconst contract = JSON.parse(readFileSync(contractPath, \"utf8\"));\nconst [command = \"check\", ...argumentsList] = process.argv.slice(2);\nconst scopeIndex = argumentsList.indexOf(\"--scope\");\nconst scopeName = scopeIndex >= 0 ? argumentsList[scopeIndex + 1] : \"repository\";\nconst shaPattern = /^[0-9a-f]{40}$/;\n\nfunction fail(message) {\n  throw new Error(message);\n}\n\nfunction pathFor(relativePath) {\n  return resolve(repositoryRoot, relativePath);\n}\n\nfunction read(relativePath) {\n  const absolutePath = pathFor(relativePath);\n  if (!existsSync(absolutePath)) {\n    fail(`缺少依赖文件：${relativePath}`);\n  }\n  return readFileSync(absolutePath, \"utf8\");\n}\n\nfunction trackedFiles(patterns) {\n  const result = spawnSync(\"git\", [\"ls-files\", \"--cached\", \"--others\", \"--exclude-standard\", \"--\", ...patterns], {\n    cwd: repositoryRoot,\n    encoding: \"utf8\",\n  });\n  if (result.status !== 0) {\n    fail(`无法读取 Git 文件清单：${result.stderr.trim()}`);\n  }\n  return result.stdout\n    .split(\"\\n\")\n    .filter(Boolean)\n    .filter((relativePath) => existsSync(pathFor(relativePath)));\n}\n\nfunction requireText(relativePath, expected, description) {\n  if (!read(relativePath).includes(expected)) {\n    fail(`${relativePath} 未满足${description}：${expected}`);\n  }\n}\n\n// 中文注释：构建与封装必须按固定顺序出现，避免只命中两个无关字符串却没有形成正式流程。\nfunction requireOrderedText(relativePath, expectedValues, description) {\n  const text = read(relativePath);\n  let offset = -1;\n  for (const expected of expectedValues) {\n    const next = text.indexOf(expected, offset + 1);\n    if (next < 0) fail(`${relativePath} 未满足${description}：${expected}`);\n    offset = next;\n  }\n}\n\nfunction escapeRegex(value) {\n  return value.replace(/[.*+?^${}()|[\\]\\\\]/g, \"\\\\$&\");\n}\n\nfunction exactCargoDependencyVersion(manifest, dependency) {\n  const tableMatch = manifest.match(new RegExp(\n    `^${escapeRegex(dependency)}\\\\s*=\\\\s*\\\\{[^\\\\n}]*\\\\bversion\\\\s*=\\\\s*\"=([^\"]+)\"`,\n    \"m\",\n  ));\n  const scalarMatch = manifest.match(new RegExp(\n    `^${escapeRegex(dependency)}\\\\s*=\\\\s*\"=([^\"]+)\"`,\n    \"m\",\n  ));\n  const match = tableMatch ?? scalarMatch;\n  if (!match) {\n    fail(`citizenchain/node/Cargo.toml 必须准确固定 ${dependency}`);\n  }\n  return match[1];\n}\n\nfunction cargoLockPackageVersion(lock, packageName) {\n  const match = lock.match(new RegExp(\n    `\\\\[\\\\[package\\\\]\\\\]\\\\r?\\\\nname = \"${escapeRegex(packageName)}\"\\\\r?\\\\nversion = \"([^\"]+)\"`,\n  ));\n  if (!match) {\n    fail(`citizenchain/Cargo.lock 缺少 ${packageName}`);\n  }\n  return match[1];\n}\n\nfunction majorMinor(version, dependency) {\n  const match = version.match(/^(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)$/);\n  if (!match) {\n    fail(`${dependency} 不是规范三段版本：${version}`);\n  }\n  return `${match[1]}.${match[2]}`;\n}\n\nfunction checkTauri() {\n  const cargoManifest = read(\"citizenchain/node/Cargo.toml\");\n  const cargoLock = read(\"citizenchain/Cargo.lock\");\n  const npmManifest = JSON.parse(read(\"citizenchain/node/frontend/package.json\"));\n  const npmLock = JSON.parse(read(\"citizenchain/node/frontend/package-lock.json\"));\n  const rootPackage = npmLock.packages?.[\"\"];\n  const rustVersions = {\n    tauri: contract.tauri.core.rust,\n    \"tauri-build\": contract.tauri.build,\n    \"tauri-plugin-dialog\": contract.tauri.plugins.dialog,\n    \"tauri-plugin-process\": contract.tauri.plugins.process,\n    \"tauri-plugin-updater\": contract.tauri.plugins.updater,\n  };\n  const npmVersions = {\n    \"@tauri-apps/api\": contract.tauri.core.api,\n    \"@tauri-apps/cli\": contract.tauri.core.cli,\n    \"@tauri-apps/plugin-dialog\": contract.tauri.plugins.dialog,\n    \"@tauri-apps/plugin-process\": contract.tauri.plugins.process,\n    \"@tauri-apps/plugin-updater\": contract.tauri.plugins.updater,\n  };\n\n  for (const [dependency, expected] of Object.entries(rustVersions)) {\n    if (exactCargoDependencyVersion(cargoManifest, dependency) !== expected) {\n      fail(`citizenchain/node/Cargo.toml 的 ${dependency} 必须准确固定为 ${expected}`);\n    }\n    if (cargoLockPackageVersion(cargoLock, dependency) !== expected) {\n      fail(`citizenchain/Cargo.lock 的 ${dependency} 必须锁定为 ${expected}`);\n    }\n  }\n  for (const [dependency, expected] of Object.entries(npmVersions)) {\n    const manifestVersion = npmManifest.dependencies?.[dependency]\n      ?? npmManifest.devDependencies?.[dependency];\n    const rootVersion = rootPackage?.dependencies?.[dependency]\n      ?? rootPackage?.devDependencies?.[dependency];\n    const lockVersion = npmLock.packages?.[`node_modules/${dependency}`]?.version;\n    if (manifestVersion !== expected || rootVersion !== expected || lockVersion !== expected) {\n      fail(`citizenchain/node/frontend 的 ${dependency} 必须在 manifest 与 lockfile 准确固定为 ${expected}`);\n    }\n  }\n  for (const [packagePath, metadata] of Object.entries(npmLock.packages ?? {})) {\n    if (packagePath.startsWith(\"node_modules/@tauri-apps/cli-\")\n      && metadata.version !== contract.tauri.core.cli) {\n      fail(`${packagePath} 必须与 @tauri-apps/cli 同为 ${contract.tauri.core.cli}`);\n    }\n  }\n\n  const coreMinor = majorMinor(contract.tauri.core.rust, \"tauri\");\n  for (const [dependency, version] of [\n    [\"@tauri-apps/api\", contract.tauri.core.api],\n    [\"@tauri-apps/cli\", contract.tauri.core.cli],\n  ]) {\n    if (majorMinor(version, dependency) !== coreMinor) {\n      fail(`Tauri core 主次版本不一致：tauri=${contract.tauri.core.rust} ${dependency}=${version}`);\n    }\n  }\n\n  const cli = \"node frontend/node_modules/@tauri-apps/cli/tauri.js\";\n  for (const workflow of contract.scopes[\"citizenchain-node\"].workflows) {\n    const text = read(workflow);\n    if (text.includes(\"cargo install tauri-cli\") || /\\bcargo tauri\\b/.test(text)) {\n      fail(`${workflow} 仍依赖浮动或全局 Tauri CLI`);\n    }\n    if (!text.includes(`${cli} build --ci -- --locked`)) {\n      fail(`${workflow} 未使用仓库锁定的 Tauri CLI 构建`);\n    }\n    if (workflow.includes(\"-release-\") && !text.includes(`${cli} signer sign`)) {\n      fail(`${workflow} 未使用仓库锁定的 Tauri CLI 签名 updater`);\n    }\n  }\n  for (const script of [\"citizenchain/scripts/run.sh\", \"citizenchain/scripts/clean-run.sh\"]) {\n    if (/\\bcargo tauri\\b/.test(read(script))) {\n      fail(`${script} 仍依赖本机全局 Tauri CLI`);\n    }\n  }\n  const runScript = \"citizenchain/scripts/run.sh\";\n  requireOrderedText(runScript, [\n    `${cli} build --no-bundle --ci -- --locked`,\n    `${cli} bundle --bundles app --ci`,\n  ], \"仓库 Tauri CLI 正式编译与封装顺序\");\n  if (read(runScript).includes(`${cli} build --bundles app --ci`)) {\n    fail(`${runScript} 禁止恢复编译与封装合并的旧 Tauri 命令`);\n  }\n  requireText(\"citizenchain/scripts/clean-run.sh\", `${cli} dev -- --locked`, \"仓库 Tauri CLI 开发构建\");\n}\n\nfunction checkRequiredFiles(scope) {\n  for (const relativePath of scope.requiredFiles) {\n    read(relativePath);\n  }\n}\n\nfunction checkPackageLocks(projects) {\n  for (const directory of projects) {\n    const manifest = JSON.parse(read(`${directory}/package.json`));\n    const lock = JSON.parse(read(`${directory}/package-lock.json`));\n    const rootPackage = lock.packages?.[\"\"];\n    if (lock.lockfileVersion !== 3) {\n      fail(`${directory}/package-lock.json 必须使用 lockfileVersion 3`);\n    }\n    if (!rootPackage || rootPackage.name !== manifest.name) {\n      fail(`${directory} 的 package.json 与 package-lock.json 包名不一致`);\n    }\n    if (manifest.version && rootPackage.version !== manifest.version) {\n      fail(`${directory} 的 package.json 与 package-lock.json 版本不一致`);\n    }\n  }\n}\n\nfunction dartScalar(relativePath, dependency) {\n  const escaped = dependency.replace(/[.*+?^${}()|[\\]\\\\]/g, \"\\\\$&\");\n  const match = read(relativePath).match(new RegExp(`^  ${escaped}:\\\\s*([^#\\\\n]+?)\\\\s*$`, \"m\"));\n  if (!match) {\n    fail(`${relativePath} 缺少统一 Dart 依赖：${dependency}`);\n  }\n  return match[1].trim();\n}\n\nfunction checkSharedDartDependencies() {\n  for (const dependency of contract.sharedDartDependencies) {\n    const appVersion = dartScalar(\"citizenapp/pubspec.yaml\", dependency);\n    const walletVersion = dartScalar(\"citizenwallet/pubspec.yaml\", dependency);\n    if (appVersion !== walletVersion) {\n      fail(`移动端共享依赖 ${dependency} 版本不一致：CitizenApp=${appVersion} CitizenWallet=${walletVersion}`);\n    }\n  }\n}\n\nfunction checkToolchains(name) {\n  const { node, rust, flutter, java, gradle } = contract.toolchains;\n  const mobileScope = name === \"repository\" || [\"citizenapp\", \"citizenwallet\"].includes(name);\n  const chainScope = name === \"repository\" || [\"citizenchain-node\", \"citizenchain-runtime\"].includes(name);\n  const nodeScope = name === \"repository\" || [\"citizenchain-node\", \"citizenserve\", \"citizenweb\"].includes(name);\n  if (mobileScope) {\n    majorMinor(flutter, \"Flutter\");\n  }\n  const rustFiles = name === \"repository\"\n    ? [\"citizenchain/rust-toolchain.toml\", \"citizenapp/smoldot/ffi/rust-toolchain.toml\"]\n    : name === \"citizenapp\"\n      ? [\"citizenapp/smoldot/ffi/rust-toolchain.toml\"]\n      : chainScope\n        ? [\"citizenchain/rust-toolchain.toml\"]\n        : [];\n  for (const file of rustFiles) {\n    requireText(file, `channel = \"${rust}\"`, \"Rust 版本统一契约\");\n  }\n  const nodeFiles = name === \"repository\"\n    ? [\"citizenchain/node/frontend/.nvmrc\", \"citizenweb/.nvmrc\"]\n    : name === \"citizenchain-node\"\n      ? [\"citizenchain/node/frontend/.nvmrc\"]\n      : name === \"citizenweb\"\n        ? [\"citizenweb/.nvmrc\"]\n        : [];\n  for (const file of nodeFiles) {\n    if (read(file).trim() !== node) {\n      fail(`${file} 必须精确固定 Node.js ${node}`);\n    }\n  }\n  const gradleFiles = name === \"repository\"\n    ? [\n        \"citizenapp/android/gradle/wrapper/gradle-wrapper.properties\",\n        \"citizenwallet/android/gradle/wrapper/gradle-wrapper.properties\",\n      ]\n    : name === \"citizenapp\"\n      ? [\"citizenapp/android/gradle/wrapper/gradle-wrapper.properties\"]\n      : name === \"citizenwallet\"\n        ? [\"citizenwallet/android/gradle/wrapper/gradle-wrapper.properties\"]\n        : [];\n  for (const file of gradleFiles) {\n    requireText(file, `gradle-${gradle}-all.zip`, \"Gradle 版本统一契约\");\n  }\n  const workflows = name === \"repository\"\n    ? trackedFiles([\n      \".github/workflows/*.yml\",\n      \".github/workflows/*.yaml\",\n      \".github/workflows/*/*.yml\",\n      \".github/workflows/*/*.yaml\",\n    ])\n    : contract.scopes[name].workflows;\n  for (const workflow of workflows) {\n    const text = read(workflow);\n    if (/node-version:\\s*(?:['\"])?24(?:['\"])?\\s*$/m.test(text)) {\n      fail(`${workflow} 仍使用浮动 Node.js 24，必须精确固定 ${node}`);\n    }\n    if (nodeScope && text.includes(\"node-version:\") && !text.includes(`node-version: ${node}`)) {\n      fail(`${workflow} 的 Node.js 版本未统一为 ${node}`);\n    }\n    if (text.includes(\"java-version:\") && !text.includes(`java-version: ${java}`)) {\n      fail(`${workflow} 的 Java 版本未统一为 ${java}`);\n    }\n  }\n}\n\nfunction checkActions(workflows) {\n  for (const [action, sha] of Object.entries(contract.actions)) {\n    if (!shaPattern.test(sha)) {\n      fail(`${action} 未配置完整 commit SHA`);\n    }\n  }\n  for (const workflow of workflows) {\n    const text = read(workflow);\n    for (const match of text.matchAll(/^\\s*uses:\\s*([^\\s#]+)(?:\\s+#.*)?$/gm)) {\n      const reference = match[1];\n      if (reference.startsWith(\"./\") || reference.startsWith(\"docker://\")) {\n        continue;\n      }\n      const separator = reference.lastIndexOf(\"@\");\n      const action = reference.slice(0, separator);\n      const revision = reference.slice(separator + 1);\n      if (!contract.actions[action]) {\n        fail(`${workflow} 使用了未登记 Action：${action}`);\n      }\n      if (revision !== contract.actions[action]) {\n        fail(`${workflow} 的 ${action} 未固定到统一 SHA ${contract.actions[action]}`);\n      }\n    }\n  }\n}\n\nfunction checkOfficialRunners(workflows) {\n  const allowed = new Set(contract.officialRunners);\n  for (const workflow of workflows) {\n    const text = read(workflow);\n    if (/runs-on:\\s*(?:\\[[^\\]]*\\bself-hosted\\b|\\bself-hosted\\b)/m.test(text)) {\n      fail(`${workflow} 使用了 self-hosted runner，必须使用统一官方镜像`);\n    }\n    const runnerLabels = [\n      ...text.matchAll(/^\\s*runs-on:\\s*((?:ubuntu|macos|windows)-[a-zA-Z0-9.-]+)\\s*$/gm),\n      ...text.matchAll(/[\"']os[\"']\\s*:\\s*[\"']((?:ubuntu|macos|windows)-[a-zA-Z0-9.-]+)[\"']/g),\n    ];\n    for (const match of runnerLabels) {\n      if (!allowed.has(match[1])) {\n        fail(`${workflow} 使用了未登记的 runner 镜像：${match[1]}`);\n      }\n    }\n  }\n}\n\nfunction checkGitDependencies(manifests) {\n  for (const manifest of manifests) {\n    const text = read(manifest);\n    if (/git\\s*=\\s*\"[^\"]+\"[^\\n}]*\\b(branch|tag)\\s*=/m.test(text)) {\n      fail(`${manifest} 存在可漂移的 Git branch/tag 依赖，必须使用 rev`);\n    }\n    for (const match of text.matchAll(/git\\s*=\\s*\"[^\"]+\"[^\\n}]*\\brev\\s*=\\s*\"([^\"]+)\"/g)) {\n      if (!shaPattern.test(match[1])) {\n        fail(`${manifest} 的 Git rev 不是完整 commit SHA：${match[1]}`);\n      }\n    }\n  }\n}\n\nfunction workflowActionScript(workflow) {\n  if (workflow === '.github/workflows/gmb-repository.yml') {\n    return '.github/scripts/gmb-repository/ci-repository.mjs';\n  }\n  return workflow.replace(/^\\.github\\/workflows\\//, '.github/scripts/').replace(/\\.ya?ml$/, '.mjs');\n}\n\nfunction checkWorkflowScopes() {\n  const productWorkflows = [];\n  const expectedWorkflows = [];\n  const legacyName = `${\"gmb-ci\"}-repository.yml`;\n  for (const [name, scope] of Object.entries(contract.scopes)) {\n    for (const workflow of scope.workflows) {\n      expectedWorkflows.push(workflow);\n      const text = read(workflow);\n      const invocation = `node ${workflowActionScript(workflow)} dependencies check --scope ${name}`;\n      if (!text.includes(invocation)) {\n        fail(`${workflow} 未调用依赖作用域：${name}`);\n      }\n      if (name !== \"repository\") {\n        productWorkflows.push(workflow);\n        if (text.includes(\"gmb-repository.yml\") || text.includes(legacyName)) {\n          fail(`${workflow} 不得调用或依赖仓库门禁`);\n        }\n      }\n    }\n  }\n  if (productWorkflows.length !== 28) {\n    fail(`产品 workflow 必须精确为 28 条，当前契约登记 ${productWorkflows.length} 条`);\n  }\n  const actualWorkflows = trackedFiles([\n    \".github/workflows/*.yml\",\n    \".github/workflows/*.yaml\",\n    \".github/workflows/*/*.yml\",\n    \".github/workflows/*/*.yaml\",\n  ]);\n  const expected = [...expectedWorkflows].sort();\n  const actual = [...actualWorkflows].sort();\n  if (JSON.stringify(actual) !== JSON.stringify(expected)) {\n    fail(`workflow 清单与依赖契约不一致：期望 ${expected.length} 条，实际 ${actual.length} 条`);\n  }\n  const legacyWorkflow = `.github/workflows/${\"gmb-ci\"}-repository.yml`;\n  if (existsSync(pathFor(legacyWorkflow))) {\n    fail(`旧仓库门禁 ${legacyWorkflow} 仍存在`);\n  }\n}\n\nfunction checkFrozenCommands(scopeNames) {\n  for (const name of scopeNames) {\n    const scope = contract.scopes[name];\n    for (const workflow of scope.workflows) {\n      const text = read(workflow);\n      if (/\\/publish-[^/]+\\.ya?ml$/.test(workflow)) continue;\n      if ([\"citizenapp\", \"citizenwallet\"].includes(name) && !text.includes(\"flutter pub get --enforce-lockfile\")) {\n        fail(`${workflow} 未冻结 Flutter/Dart 应用依赖`);\n      }\n      if ([\"citizenserve\", \"citizenweb\"].includes(name) && !text.includes(\"npm ci\")) {\n        fail(`${workflow} 未使用 npm ci`);\n      }\n      if ([\"citizenchain-node\", \"citizenchain-runtime\"].includes(name) && !text.includes(\"--locked\")) {\n        fail(`${workflow} 未冻结 Cargo 依赖`);\n      }\n    }\n  }\n}\n\nfunction checkAuditGates(scopeNames) {\n  for (const name of scopeNames) {\n    const scope = contract.scopes[name];\n    const audited = contract.auditedScopes.includes(name);\n    const hasCargo = contract.cargoProjects.some((directory) =>\n      scope.requiredFiles.includes(projectFile(directory, \"Cargo.toml\")));\n    for (const workflow of scope.workflows) {\n      const invocation = `node ${workflowActionScript(workflow)} dependencies audit --scope ${name}`;\n      const text = read(workflow);\n      if (/\\/publish-[^/]+\\.ya?ml$/.test(workflow)) {\n        if (text.includes(invocation)) fail(`${workflow} 不得重建或审计已固化正式 Release`);\n        continue;\n      }\n      if (audited && !text.includes(invocation)) {\n        fail(`${workflow} 未接入已清零产品的阻断安全审计：${name}`);\n      }\n      if (!audited && text.includes(invocation)) {\n        fail(`${workflow} 接入了尚未登记零漏洞基线的安全审计：${name}`);\n      }\n      if (audited && hasCargo && !text.includes(\n        `cargo install cargo-audit --version ${contract.toolchains.cargoAudit} --locked`,\n      )) {\n        fail(`${workflow} 未安装固定版本 cargo-audit ${contract.toolchains.cargoAudit}`);\n      }\n    }\n  }\n}\n\nfunction checkScope(name) {\n  const scope = contract.scopes[name];\n  if (!scope) {\n    fail(`未知依赖作用域：${name}`);\n  }\n  checkRequiredFiles(scope);\n  if (name === \"repository\" || name === \"citizenchain-node\") {\n    checkTauri();\n  }\n  if (name === \"repository\") {\n    for (const candidate of Object.values(contract.scopes)) {\n      checkRequiredFiles(candidate);\n    }\n    checkPackageLocks(contract.npmProjects);\n    for (const directory of contract.dartApplications) {\n      read(`${directory}/pubspec.yaml`);\n      read(`${directory}/pubspec.lock`);\n    }\n    for (const directory of contract.cargoProjects) {\n      read(`${directory}/Cargo.toml`);\n      read(`${directory}/Cargo.lock`);\n    }\n    checkSharedDartDependencies();\n    checkToolchains(name);\n    const workflows = trackedFiles([\n      \".github/workflows/*.yml\",\n      \".github/workflows/*.yaml\",\n      \".github/workflows/*/*.yml\",\n      \".github/workflows/*/*.yaml\",\n    ]);\n    checkActions(workflows);\n    checkOfficialRunners(workflows);\n    checkGitDependencies(trackedFiles([\"**/Cargo.toml\", \"Cargo.toml\"]));\n    checkWorkflowScopes();\n    checkFrozenCommands(Object.keys(contract.scopes));\n    checkAuditGates(Object.keys(contract.scopes));\n  } else {\n    checkPackageLocks(contract.npmProjects.filter((directory) =>\n      scope.requiredFiles.includes(`${directory}/package.json`)));\n    checkToolchains(name);\n    checkActions(scope.workflows);\n    checkOfficialRunners(scope.workflows);\n    checkGitDependencies(scope.requiredFiles.filter((file) => file.endsWith(\"Cargo.toml\")));\n    checkFrozenCommands([name]);\n    checkAuditGates([name]);\n    for (const workflow of scope.workflows) {\n      const invocation = `node ${workflowActionScript(workflow)} dependencies check --scope ${name}`;\n      requireText(workflow, invocation, \"产品依赖作用域检查\");\n    }\n  }\n  console.log(`依赖检查通过：${name}`);\n}\n\nfunction projectFile(directory, fileName) {\n  return directory === \".\" ? fileName : `${directory}/${fileName}`;\n}\n\nfunction scopedProjects(projects, fileName) {\n  if (scopeName === \"repository\") {\n    return projects;\n  }\n  const requiredFiles = contract.scopes[scopeName]?.requiredFiles;\n  if (!requiredFiles) {\n    fail(`未知依赖作用域：${scopeName}`);\n  }\n  return projects.filter((directory) => requiredFiles.includes(projectFile(directory, fileName)));\n}\n\nfunction runNative(executable, argumentsValue, cwd, allowFailure = false) {\n  console.log(`\\n[${cwd}] ${executable} ${argumentsValue.join(\" \")}`);\n  const result = spawnSync(executable, argumentsValue, {\n    cwd: pathFor(cwd),\n    encoding: \"utf8\",\n    stdio: \"inherit\",\n  });\n  if (result.error) {\n    fail(`无法执行 ${executable}：${result.error.message}`);\n  }\n  if (result.status !== 0 && !allowFailure) {\n    fail(`${executable} 检查失败，退出码 ${result.status}`);\n  }\n}\n\nfunction audit() {\n  checkScope(scopeName);\n  const npmProjects = scopedProjects(contract.npmProjects, \"package.json\");\n  const cargoProjects = scopedProjects(contract.cargoProjects, \"Cargo.toml\");\n  for (const directory of npmProjects) {\n    runNative(\"npm\", [\"audit\", \"--audit-level=low\"], directory);\n  }\n  if (cargoProjects.length > 0) {\n    const auditVersion = spawnSync(\"cargo\", [\"audit\", \"--version\"], { encoding: \"utf8\" });\n    if (auditVersion.status !== 0 || !auditVersion.stdout.includes(contract.toolchains.cargoAudit)) {\n      fail(`cargo-audit 必须安装并固定为 ${contract.toolchains.cargoAudit}`);\n    }\n    for (const [index, directory] of cargoProjects.entries()) {\n      const argumentsValue = [\"audit\"];\n      if (index > 0) {\n        argumentsValue.push(\"--no-fetch\");\n      }\n      argumentsValue.push(\"--file\", projectFile(directory, \"Cargo.lock\"));\n      runNative(\"cargo\", argumentsValue, \".\");\n    }\n  }\n}\n\nfunction outdated() {\n  checkScope(scopeName);\n  for (const directory of scopedProjects(contract.npmProjects, \"package.json\")) {\n    runNative(\"npm\", [\"outdated\"], directory, true);\n  }\n  for (const directory of scopedProjects(contract.dartApplications, \"pubspec.yaml\")) {\n    runNative(\"dart\", [\"pub\", \"outdated\"], directory, true);\n  }\n  for (const directory of scopedProjects(contract.cargoProjects, \"Cargo.toml\")) {\n    runNative(\"cargo\", [\"update\", \"--dry-run\", \"--manifest-path\", projectFile(directory, \"Cargo.toml\")], \".\", true);\n  }\n  console.log(\"\\n过期版本仅报告；更新 manifest/lockfile 后必须重新执行产品真实验收。\");\n}\n\ntry {\n  if (contract.schema !== 1) {\n    fail(`不支持依赖契约 schema：${contract.schema}`);\n  }\n  if (command === \"check\") {\n    checkScope(scopeName);\n  } else if (command === \"audit\") {\n    audit();\n  } else if (command === \"outdated\") {\n    outdated();\n  } else {\n    fail(`未知命令：${command}`);\n  }\n} catch (error) {\n  console.error(`依赖检查失败：${error.message}`);\n  process.exitCode = 1;\n}\n","version-tag":"#!/usr/bin/env node\n\nimport { execFileSync } from 'node:child_process';\nimport { readFileSync } from 'node:fs';\nimport { pathToFileURL } from 'node:url';\n\nconst semanticVersionPattern = /^(0|[1-9]\\d*)\\.(0|[1-9]\\d?)\\.(0|[1-9]\\d?)$/;\nconst tagPrefixPattern = /^[a-z0-9][a-z0-9-]*-v$/;\nconst sourceSHAPattern = /^[0-9a-f]{40}$/;\nconst workflowFilePattern = /^(?:[a-z0-9-]+\\/)*[a-z0-9-]+\\.ya?ml$/;\n\nexport function validateWorkflowFileName(value) {\n  if (!workflowFilePattern.test(String(value))) throw new Error('workflow 无效');\n  return value;\n}\n\nexport function parseSemanticVersion(value) {\n  const match = semanticVersionPattern.exec(String(value));\n  if (!match) throw new Error(`软件版本必须形如 a.b.c 且 b、c 不超过 99：${value}`);\n  return match.slice(1).map(Number);\n}\n\nexport function compareSemanticVersions(left, right) {\n  const a = parseSemanticVersion(left);\n  const b = parseSemanticVersion(right);\n  for (let index = 0; index < 3; index += 1) {\n    if (a[index] !== b[index]) return a[index] - b[index];\n  }\n  return 0;\n}\n\nexport function nextSemanticVersion(value) {\n  let [major, minor, patch] = parseSemanticVersion(value);\n  patch += 1;\n  if (patch > 99) {\n    patch = 0;\n    minor += 1;\n  }\n  if (minor > 99) {\n    minor = 0;\n    major += 1;\n  }\n  return `${major}.${minor}.${patch}`;\n}\n\nexport function expectedSemanticCandidate(seed, successfulVersions) {\n  parseSemanticVersion(seed);\n  const normalized = [...new Set(successfulVersions.map((value) => {\n    parseSemanticVersion(value);\n    return value;\n  }))].sort(compareSemanticVersions);\n  return nextSemanticVersion(normalized.length === 0 ? seed : normalized.at(-1));\n}\n\nfunction parseArguments(argv) {\n  const [command, ...rest] = argv;\n  if (!command) throw new Error('缺少版本命令');\n  const values = {};\n  for (let index = 0; index < rest.length; index += 2) {\n    const key = rest[index];\n    const value = rest[index + 1];\n    if (!key?.startsWith('--') || value === undefined) throw new Error(`参数格式无效：${key ?? ''}`);\n    const name = key.slice(2);\n    if (Object.hasOwn(values, name)) throw new Error(`参数重复：${key}`);\n    values[name] = value;\n  }\n  return { command, values };\n}\n\nfunction requireExactKeys(values, required, optional = []) {\n  const allowed = new Set([...required, ...optional]);\n  for (const key of Object.keys(values)) {\n    if (!allowed.has(key)) throw new Error(`不支持的参数：--${key}`);\n  }\n  for (const key of required) {\n    if (!Object.hasOwn(values, key) || values[key] === '') throw new Error(`缺少参数：--${key}`);\n  }\n}\n\nfunction ghJSON(path) {\n  const output = execFileSync('gh', ['api', path], {\n    encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'],\n  });\n  try {\n    return JSON.parse(output);\n  } catch {\n    throw new Error(`GitHub API 返回了无效 JSON：${path}`);\n  }\n}\n\nfunction readSeed(kind, path) {\n  const text = readFileSync(path, 'utf8');\n  if (kind === 'json') {\n    const value = JSON.parse(text)?.version;\n    parseSemanticVersion(value);\n    return value;\n  }\n  if (kind === 'pubspec') {\n    const matches = [...text.matchAll(/^version:\\s*([^+\\s]+)(?:\\+\\d+)?\\s*$/gm)];\n    if (matches.length !== 1) throw new Error(`pubspec 软件版本真源不唯一：${path}`);\n    parseSemanticVersion(matches[0][1]);\n    return matches[0][1];\n  }\n  throw new Error(`不支持的版本真源类型：${kind}`);\n}\n\nfunction publishedSemanticVersions(prefix) {\n  if (!tagPrefixPattern.test(prefix)) throw new Error('Tag 前缀无效');\n  const escaped = prefix.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&');\n  const pattern = new RegExp(`^${escaped}(${semanticVersionPattern.source.slice(1, -1)})$`);\n  const versions = [];\n  for (let page = 1; page <= 100; page += 1) {\n    const releases = ghJSON(`repos/{owner}/{repo}/releases?per_page=100&page=${page}`);\n    if (!Array.isArray(releases)) throw new Error('GitHub Release 列表格式无效');\n    for (const release of releases) {\n      if (release?.draft === true || release?.prerelease === true) continue;\n      const tag = String(release?.tag_name || '');\n      if (!tag.startsWith(prefix)) continue;\n      const match = pattern.exec(tag);\n      if (!match) throw new Error(`同前缀正式 Release Tag 不符合统一版本契约：${tag}`);\n      parseSemanticVersion(match[1]);\n      versions.push(match[1]);\n    }\n    if (releases.length < 100) return versions;\n  }\n  throw new Error('GitHub Release 列表超过安全分页上限');\n}\n\nfunction validateIdentity(values) {\n  if (!/^[a-z][a-z0-9-]*$/.test(values['product-id'])) throw new Error('product_id 无效');\n  if (!/^[a-z][a-z0-9-]*$/.test(values.target)) throw new Error('target 无效');\n  validateWorkflowFileName(values.workflow);\n  if (!sourceSHAPattern.test(values['source-sha'])) throw new Error('source_sha 无效');\n  if (!/^[1-9]\\d*$/.test(values['ci-run-id'])) throw new Error('ci_run_id 无效');\n}\n\nfunction verifySuccessfulCIRun(values) {\n  validateIdentity(values);\n  const run = ghJSON(`repos/{owner}/{repo}/actions/runs/${values['ci-run-id']}`);\n  if (run.status !== 'completed' || run.conclusion !== 'success'\n    || run.event !== 'workflow_dispatch' || run.head_branch !== 'main'\n    || run.head_sha !== values['source-sha']\n    || !String(run.path || '').endsWith(`/${values.workflow}`)) {\n    throw new Error('Release 来源不是同产品、同端、同 workflow 的成功 CI');\n  }\n  const head = execFileSync('git', ['rev-parse', 'HEAD'], { encoding: 'utf8' }).trim();\n  if (head !== values['source-sha']) throw new Error(`checkout 与 source_sha 不一致：${head}`);\n}\n\n// Runtime 正式版本只由 Release 确定；CI 仅证明同一源码已通过验证，因此这里校验\n// Release 的 spec_version 与正式 Tag 一致，不再从 CI 诊断产物读取版本候选。\nfunction verifyRuntimeVersion(values) {\n  const specVersion = Number(values['spec-version']);\n  if (!/^[1-9]\\d*$/.test(values['spec-version'])\n    || !Number.isSafeInteger(specVersion) || specVersion > 2 ** 32 - 1) {\n    throw new Error('spec_version 无效');\n  }\n}\n\nfunction printNextSemanticRelease(values) {\n  requireExactKeys(values, ['prefix', 'seed']);\n  const candidate = expectedSemanticCandidate(\n    values.seed,\n    publishedSemanticVersions(values.prefix),\n  );\n  process.stdout.write(`${candidate}\\n`);\n}\n\nfunction verifyReleaseSource(values) {\n  requireExactKeys(values, [\n    'version-tag', 'source-sha', 'ci-run-id', 'prefix', 'product-id', 'target', 'workflow',\n  ], ['spec-version']);\n  if (!tagPrefixPattern.test(values.prefix)\n    || !values['version-tag'].startsWith(values.prefix)\n    || !/^[a-z0-9][a-z0-9.-]*$/.test(values['version-tag'])) {\n    throw new Error('Release 版本 Tag 身份无效');\n  }\n  verifySuccessfulCIRun(values);\n  const suffix = values['version-tag'].slice(values.prefix.length);\n  if (Object.hasOwn(values, 'spec-version')) {\n    if (values['product-id'] !== 'citizenchain-runtime'\n      || suffix !== values['spec-version']) throw new Error('Runtime Release 版本参数无效');\n    verifyRuntimeVersion(values);\n  } else {\n    const seedSources = {\n      citizenapp: ['pubspec', 'citizenapp/pubspec.yaml'],\n      citizenwallet: ['pubspec', 'citizenwallet/pubspec.yaml'],\n      'citizenchain-node': ['json', 'citizenchain/node/tauri.conf.json'],\n      citizenserve: ['json', 'citizenserve/package.json'],\n      citizenweb: ['json', 'citizenweb/package.json'],\n    };\n    const source = seedSources[values['product-id']];\n    if (!source) throw new Error('语义版本 Release 缺少版本真源');\n    parseSemanticVersion(suffix);\n    const expected = expectedSemanticCandidate(\n      readSeed(source[0], source[1]),\n      publishedSemanticVersions(values.prefix),\n    );\n    if (suffix !== expected) {\n      throw new Error(`Release 版本不是正式 Release 真源的下一版本：期望 ${expected}，收到 ${suffix}`);\n    }\n  }\n  process.stdout.write(`Release 已锁定成功 CI：${values['ci-run-id']} · ${values['source-sha']}\\n`);\n}\n\nexport function main(argv) {\n  const { command, values } = parseArguments(argv);\n  if (command === 'next-semantic-release') return printNextSemanticRelease(values);\n  if (command === 'verify-release-source') return verifyReleaseSource(values);\n  throw new Error(`不支持的版本命令：${command}`);\n}\n\nif (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {\n  try {\n    main(process.argv.slice(2));\n  } catch (error) {\n    process.stderr.write(`${error instanceof Error ? error.message : String(error)}\\n`);\n    process.exitCode = 1;\n  }\n}\n","github-release":"#!/usr/bin/env node\n\nimport { lstatSync } from 'node:fs';\nimport { basename } from 'node:path';\nimport { spawnSync } from 'node:child_process';\nimport { pathToFileURL } from 'node:url';\n\nconst SHA_PATTERN = /^[0-9a-f]{40}$/;\nconst REPOSITORY_PATTERN = /^[A-Za-z0-9_.-]+\\/[A-Za-z0-9_.-]+$/;\nconst TAG_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]{0,199}$/;\nconst READ_ATTEMPTS = 7;\nconst READ_RETRY_MS = 10_000;\n\nfunction required(condition, message) {\n  if (!condition) throw new Error(message);\n}\n\nexport function gh(args, options = {}) {\n  const run = options.run || spawnSync;\n  const wait = options.wait || ((milliseconds) => {\n    Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, milliseconds);\n  });\n  const attempts = options.retryRead ? READ_ATTEMPTS : 1;\n  for (let attempt = 1; attempt <= attempts; attempt += 1) {\n    const result = run('gh', args, {\n      encoding: 'utf8',\n      input: options.input,\n      env: process.env,\n      maxBuffer: 16 * 1024 * 1024,\n    });\n    if (result.error) throw result.error;\n    if (result.status === 0) return String(result.stdout || '').trim();\n    const detail = String(result.stderr || result.stdout || '').trim();\n    if (options.notFound && /(?:HTTP 404|Not Found)/i.test(detail)) return null;\n    // 中文注释：GitHub 偶发把具有 Contents write 的 Actions 令牌拒绝在只读 Release\n    // 查询上；只重试幂等读取，创建、发布与删除事务绝不自动重放。\n    const integrationDenied = /HTTP 403:\\s*Resource not accessible by integration/i.test(detail);\n    const retryable = options.retryRead && (integrationDenied || /HTTP 5\\d\\d/i.test(detail));\n    if (!retryable || attempt === attempts) {\n      throw new Error(detail || `gh 执行失败，退出码 ${result.status}`);\n    }\n    console.error(`[GitHub] Release 只读接口暂时不可用，${READ_RETRY_MS / 1000} 秒后重试（${attempt}/${attempts - 1}）`);\n    wait(READ_RETRY_MS);\n  }\n  throw new Error('GitHub Release 只读接口重试状态异常');\n}\n\nfunction json(output, context) {\n  try {\n    return JSON.parse(output);\n  } catch {\n    throw new Error(`${context}返回了无效 JSON`);\n  }\n}\n\nexport function createClient() {\n  return {\n    async listReleases(repository) {\n      const releases = [];\n      for (let page = 1; page <= 100; page += 1) {\n        const output = gh(['api', `repos/${repository}/releases?per_page=100&page=${page}`], {\n          retryRead: true,\n        });\n        const values = json(output, 'GitHub Release 列表');\n        required(Array.isArray(values), 'GitHub Release 列表格式无效');\n        releases.push(...values);\n        if (values.length < 100) return releases;\n      }\n      throw new Error('GitHub Release 列表超过安全分页上限');\n    },\n    async getTag(repository, tag) {\n      const output = gh(['api', `repos/${repository}/git/ref/tags/${encodeURIComponent(tag)}`], {\n        notFound: true,\n        retryRead: true,\n      });\n      return output === null ? null : json(output, 'GitHub Tag');\n    },\n    async getTagObject(repository, objectSHA) {\n      return json(gh(['api', `repos/${repository}/git/tags/${objectSHA}`], { retryRead: true }), 'GitHub Tag 对象');\n    },\n    async createTag(repository, tag, releaseSHA) {\n      const payload = JSON.stringify({ ref: `refs/tags/${tag}`, sha: releaseSHA });\n      gh(['api', '--method', 'POST', `repos/${repository}/git/refs`, '--input', '-'], {\n        input: payload,\n      });\n    },\n    async createDraft(input) {\n      const args = [\n        'release', 'create', input.tag, '--repo', input.repository,\n        '--verify-tag', '--draft', '--title', input.title,\n      ];\n      if (input.notes) args.push('--notes', input.notes);\n      else args.push('--notes-file', input.notesFile);\n      args.push(...input.assets.map((asset) => asset.path));\n      // 中文注释：版本 Tag 已在同一 Release 事务中准确绑定本次 Release\n      // workflow 提交；成功 CI 提交只是正式构建与产物来源，不冒充 Tag 目标。\n      gh(args);\n    },\n    async getRelease(repository, releaseId) {\n      return json(gh(['api', `repos/${repository}/releases/${releaseId}`], { retryRead: true }), 'GitHub Release');\n    },\n    async getReleaseByTag(repository, tag) {\n      const output = gh(\n        ['api', `repos/${repository}/releases/tags/${encodeURIComponent(tag)}`],\n        { notFound: true, retryRead: true },\n      );\n      return output === null ? null : json(output, 'GitHub Tag Release');\n    },\n    async publish(repository, releaseId, latest) {\n      const payload = JSON.stringify({ draft: false, make_latest: latest ? 'true' : 'false' });\n      gh(['api', '--method', 'PATCH', `repos/${repository}/releases/${releaseId}`, '--input', '-'], {\n        input: payload,\n      });\n    },\n    async deleteRelease(repository, releaseId) {\n      gh(['api', '--method', 'DELETE', `repos/${repository}/releases/${releaseId}`]);\n    },\n    async deleteTag(repository, tag) {\n      gh(['api', '--method', 'DELETE', `repos/${repository}/git/refs/tags/${encodeURIComponent(tag)}`]);\n    },\n    async wait() {\n      await new Promise((resolve) => setTimeout(resolve, 1_000));\n    },\n  };\n}\n\nfunction verifyAssets(release, assets) {\n  required(Array.isArray(release.assets), 'GitHub Release 资产格式无效');\n  required(release.assets.length === assets.length, 'GitHub Release 资产数量不符');\n  const actual = new Map();\n  for (const asset of release.assets) {\n    required(typeof asset?.name === 'string' && !actual.has(asset.name), 'GitHub Release 资产名称重复或无效');\n    actual.set(asset.name, asset);\n  }\n  for (const expected of assets) {\n    const asset = actual.get(expected.name);\n    required(asset, `GitHub Release 缺少资产：${expected.name}`);\n    required(asset.state === 'uploaded', `GitHub Release 资产未完成上传：${expected.name}`);\n    required(asset.size === expected.size, `GitHub Release 资产大小不符：${expected.name}`);\n  }\n}\n\nfunction verifyRelease(release, input, draft) {\n  required(Number.isSafeInteger(release?.id) && release.id > 0, 'GitHub Release id 无效');\n  required(release.tag_name === input.tag, 'GitHub 版本 Tag 不符');\n  required(release.name === input.title, 'GitHub Release 标题不符');\n  required(release.draft === draft, draft ? 'GitHub Release 不是草稿' : 'GitHub Release 尚未固化');\n  verifyAssets(release, input.assets);\n}\n\n// 中文注释：草稿没有稳定的最终 Tag 查询入口，只能从含草稿的 Release 列表取得唯一数字 id。\nasync function findDraft(client, input) {\n  for (let attempt = 0; attempt < 5; attempt += 1) {\n    const matches = (await client.listReleases(input.repository))\n      .filter((value) => value?.tag_name === input.tag\n        && value?.name === input.title && value?.draft === true);\n    required(matches.length <= 1, `发现多个同名 GitHub Release：${input.tag}`);\n    if (matches.length === 1) return matches[0];\n    await client.wait();\n  }\n  return null;\n}\n\nasync function versionTagCommit(client, input) {\n  const reference = await client.getTag(input.repository, input.tag);\n  required(reference?.ref === `refs/tags/${input.tag}`\n    && SHA_PATTERN.test(String(reference?.object?.sha || '')), '正式版本 Tag 不存在或无效');\n  if (reference.object.type === 'commit') {\n    required(reference.object.sha === input.releaseSHA, '正式版本 Tag 未指向本次 Release 提交');\n    return reference.object.sha;\n  }\n  required(reference.object.type === 'tag', '正式版本 Tag 类型无效');\n  const object = await client.getTagObject(input.repository, reference.object.sha);\n  required(object?.tag === input.tag && object?.object?.type === 'commit'\n    && object.object.sha === input.releaseSHA, '正式版本 Tag 未指向本次 Release 提交');\n  return object.object.sha;\n}\n\nexport async function release(input, client = createClient()) {\n  let releaseId = null;\n  let transactionStarted = false;\n  let reuseExistingTag = false;\n  const existing = (await client.listReleases(input.repository))\n    .filter((value) => value?.tag_name === input.tag);\n  const published = existing.filter((value) => value?.draft === false);\n  required(published.length === 0, `正式 Release 已存在，禁止覆盖：${input.tag}`);\n  const drafts = existing.filter((value) => value?.draft === true);\n  required(drafts.length <= 1, `发现多个同 Tag 草稿 Release：${input.tag}`);\n  if (drafts.length === 1) {\n    // 中文注释：新事务以真实 Tag 指向为准；仅兼容清理旧工具尚未建 Tag、但已准确\n    // 记录成功 CI 源提交的草稿，不保留旧发布流程。\n    const draftTag = await client.getTag(input.repository, input.tag);\n    if (draftTag) {\n      await versionTagCommit(client, input);\n    } else {\n      required(drafts[0]?.target_commitish === input.sourceSHA,\n        '遗留草稿未绑定本次成功 CI 源提交，禁止清理');\n    }\n    await client.deleteRelease(input.repository, drafts[0].id);\n    if (draftTag) await client.deleteTag(input.repository, input.tag);\n  } else {\n    const staleTag = await client.getTag(input.repository, input.tag);\n    if (staleTag) {\n      // 中文注释：上次事务如在创建 Tag 后中断，本次只复用准确指向\n      // 当前 Release workflow 提交的 Tag，禁止复用任意旧源码 Tag。\n      await versionTagCommit(client, input);\n      reuseExistingTag = true;\n    }\n  }\n\n  try {\n    transactionStarted = true;\n    // 中文注释：Release 独占版本推进；先为本次 Release workflow 提交创建\n    // 精确轻量 Tag，再要求草稿复用该 Tag。正式资产仍严格来自 sourceSHA。\n    // 任一后续步骤失败都会在本事务中回滚，失败任务不会占用版本号。\n    if (!reuseExistingTag) await client.createTag(input.repository, input.tag, input.releaseSHA);\n    await client.createDraft(input);\n    let draft = await findDraft(client, input);\n    required(draft, `无法取得新建草稿 Release：${input.tag}`);\n    releaseId = draft.id;\n    draft = await client.getRelease(input.repository, releaseId);\n    verifyRelease(draft, input, true);\n    // 中文注释：草稿资产全部校验通过后再发布，已有事务 Tag 此时才成为正式版本入口。\n    await client.publish(input.repository, releaseId, input.latest);\n\n    const result = await client.getRelease(input.repository, releaseId);\n    verifyRelease(result, input, false);\n    const byTag = await client.getReleaseByTag(input.repository, input.tag);\n    required(byTag?.id === releaseId, '版本 Tag 未关联本次 GitHub Release');\n    await versionTagCommit(client, input);\n    console.log(`正式 Release 与唯一版本 Tag 已固化：${input.tag}`);\n    return result;\n  } catch (error) {\n    const cleanupErrors = [];\n    if (transactionStarted) {\n      try {\n        if (releaseId) await client.deleteRelease(input.repository, releaseId);\n        else {\n          const draft = await findDraft(client, input);\n          if (draft) await client.deleteRelease(input.repository, draft.id);\n        }\n      } catch (cleanupError) {\n        cleanupErrors.push(`草稿回滚失败：${cleanupError.message}`);\n      }\n      try {\n        const tag = await client.getTag(input.repository, input.tag);\n        if (tag) {\n          await versionTagCommit(client, input);\n          await client.deleteTag(input.repository, input.tag);\n        }\n      } catch (cleanupError) {\n        cleanupErrors.push(`Tag 回滚失败：${cleanupError.message}`);\n      }\n    }\n    const suffix = cleanupErrors.length > 0 ? `；${cleanupErrors.join('；')}` : '';\n    throw new Error(`${error.message}${suffix}`);\n  }\n}\n\nexport function parseArgs(argv, environment = process.env) {\n  const values = new Map();\n  const assetIndex = argv.indexOf('--assets');\n  required(assetIndex >= 0 && assetIndex < argv.length - 1, '缺少 --assets');\n  const assetPaths = argv.slice(assetIndex + 1);\n  const optionArgs = argv.slice(0, assetIndex);\n  required(optionArgs.length % 2 === 0, 'Release 参数必须成对提供');\n  for (let index = 0; index < optionArgs.length; index += 2) {\n    const key = optionArgs[index];\n    required(/^--[a-z-]+$/.test(key) && !values.has(key), `Release 参数无效或重复：${key}`);\n    values.set(key, optionArgs[index + 1]);\n  }\n\n  const repository = environment.GITHUB_REPOSITORY;\n  const releaseSHA = environment.GITHUB_SHA;\n  const tag = values.get('--tag');\n  const sourceSHA = values.get('--source-sha');\n  const title = values.get('--title');\n  const notes = values.get('--notes');\n  const notesFile = values.get('--notes-file');\n  const latestValue = values.get('--latest');\n  required(REPOSITORY_PATTERN.test(repository || ''), 'GITHUB_REPOSITORY 无效');\n  required(SHA_PATTERN.test(releaseSHA || ''), 'Release workflow 提交无效');\n  required(TAG_PATTERN.test(tag || ''), '版本 Tag 无效');\n  required(SHA_PATTERN.test(sourceSHA || ''), 'Release 源提交无效');\n  required(typeof title === 'string' && title.trim() === title && title.length > 0, 'Release 标题无效');\n  required(Boolean(notes) !== Boolean(notesFile), '必须且只能提供 --notes 或 --notes-file');\n  required(latestValue === 'true' || latestValue === 'false', '--latest 只允许 true 或 false');\n\n  const assets = assetPaths.map((path) => {\n    const value = lstatSync(path);\n    required(value.isFile() && value.size > 0, `Release 资产不是非空普通文件：${path}`);\n    return { path, name: basename(path), size: value.size };\n  });\n  required(new Set(assets.map((asset) => asset.name)).size === assets.length, 'Release 资产文件名重复');\n  return {\n    repository,\n    releaseSHA,\n    tag,\n    sourceSHA,\n    title,\n    notes,\n    notesFile,\n    latest: latestValue === 'true',\n    assets,\n  };\n}\n\nif (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {\n  try {\n    await release(parseArgs(process.argv.slice(2)));\n  } catch (error) {\n    console.error(error.message);\n    process.exitCode = 1;\n  }\n}\n","linux-deps":"#!/usr/bin/env bash\n\nset -euo pipefail\n\n# 中文注释：GitHub Ubuntu Runner 默认优先使用 Azure 区域镜像，该镜像偶发卡住时\n# Acquire::Retries 无法保证整条 apt-get 命令及时退出。这里为当前命令提供独立官方源，\n# 不改写 Runner 的全局 sources 文件，也不访问与 CitizenChain 构建无关的第三方仓库。\n# shellcheck disable=SC1091\nsource /etc/os-release\n\nif [[ \"${ID:-}\" != \"ubuntu\" || -z \"${VERSION_CODENAME:-}\" ]]; then\n  echo \"::error::只支持带 VERSION_CODENAME 的 Ubuntu Runner\"\n  exit 1\nfi\n\ncitizenchain_arch=\"$(dpkg --print-architecture)\"\ncitizenchain_source=\"$(mktemp)\"\ntrap 'rm -f \"${citizenchain_source}\"' EXIT\n\ncase \"${citizenchain_arch}\" in\n  amd64)\n    citizenchain_archive=\"https://archive.ubuntu.com/ubuntu\"\n    citizenchain_security=\"https://security.ubuntu.com/ubuntu\"\n    ;;\n  arm64)\n    citizenchain_archive=\"https://ports.ubuntu.com/ubuntu-ports\"\n    citizenchain_security=\"${citizenchain_archive}\"\n    ;;\n  *)\n    echo \"::error::不支持的 Ubuntu 架构：${citizenchain_arch}\"\n    exit 1\n    ;;\nesac\n\n{\n  echo \"deb [arch=${citizenchain_arch} signed-by=/usr/share/keyrings/ubuntu-archive-keyring.gpg] ${citizenchain_archive} ${VERSION_CODENAME} main restricted universe multiverse\"\n  echo \"deb [arch=${citizenchain_arch} signed-by=/usr/share/keyrings/ubuntu-archive-keyring.gpg] ${citizenchain_archive} ${VERSION_CODENAME}-updates main restricted universe multiverse\"\n  echo \"deb [arch=${citizenchain_arch} signed-by=/usr/share/keyrings/ubuntu-archive-keyring.gpg] ${citizenchain_archive} ${VERSION_CODENAME}-backports main restricted universe multiverse\"\n  echo \"deb [arch=${citizenchain_arch} signed-by=/usr/share/keyrings/ubuntu-archive-keyring.gpg] ${citizenchain_security} ${VERSION_CODENAME}-security main restricted universe multiverse\"\n} > \"${citizenchain_source}\"\n\ncitizenchain_apt_options=(\n  -o \"Dir::Etc::sourcelist=${citizenchain_source}\"\n  -o \"Dir::Etc::sourceparts=-\"\n  -o Acquire::Retries=2\n  -o Acquire::http::Timeout=20\n  -o Acquire::https::Timeout=20\n  -o Acquire::Languages=none\n)\n\ncitizenchain_packages=(\n  clang\n  llvm\n  llvm-dev\n  libclang-dev\n  libpam0g-dev\n  libssl-dev\n  libwebkit2gtk-4.1-dev\n  libgtk-3-dev\n  libayatana-appindicator3-dev\n  librsvg2-dev\n  pkg-config\n  protobuf-compiler\n  patchelf\n  file\n)\n\nrun_apt() {\n  local citizenchain_label=\"$1\"\n  local citizenchain_timeout=\"$2\"\n  shift 2\n\n  local citizenchain_attempt\n  local citizenchain_status=1\n  for citizenchain_attempt in 1 2 3; do\n    echo \"${citizenchain_label}：第 ${citizenchain_attempt}/3 次\"\n    if timeout --signal=TERM --kill-after=15s \"${citizenchain_timeout}\" \"$@\"; then\n      return 0\n    else\n      citizenchain_status=$?\n    fi\n\n    if [[ \"${citizenchain_attempt}\" -lt 3 ]]; then\n      # 中文注释：重试整条 APT 事务，避免单个 Acquire 重试耗尽后直接终止产品流水线。\n      sleep \"$((citizenchain_attempt * 10))\"\n    fi\n  done\n\n  echo \"::error::${citizenchain_label}连续三次失败，最后退出码为 ${citizenchain_status}\"\n  return \"${citizenchain_status}\"\n}\n\nrun_apt \\\n  \"更新 CitizenChain Linux 官方软件源\" \\\n  4m \\\n  sudo env DEBIAN_FRONTEND=noninteractive apt-get \\\n    \"${citizenchain_apt_options[@]}\" update\n\nrun_apt \\\n  \"安装 CitizenChain Linux 系统依赖\" \\\n  8m \\\n  sudo env DEBIAN_FRONTEND=noninteractive apt-get \\\n    \"${citizenchain_apt_options[@]}\" install -y \\\n    \"${citizenchain_packages[@]}\"\n\n# 中文注释：APT 成功退出后再回读包状态和关键命令，禁止缺少依赖时进入 Rust/前端构建。\nfor citizenchain_package in \"${citizenchain_packages[@]}\"; do\n  if [[ \"$(dpkg-query -W -f='${Status}' \"${citizenchain_package}\" 2>/dev/null || true)\" != \"install ok installed\" ]]; then\n    echo \"::error::CitizenChain Linux 依赖未安装：${citizenchain_package}\"\n    exit 1\n  fi\ndone\n\nfor citizenchain_command in clang llvm-config pkg-config protoc patchelf file; do\n  if ! command -v \"${citizenchain_command}\" >/dev/null 2>&1; then\n    echo \"::error::CitizenChain Linux 构建命令不可用：${citizenchain_command}\"\n    exit 1\n  fi\ndone\n\necho \"CitizenChain Linux 系统依赖已通过官方 Ubuntu 源安装并回读验证。\"\n"});
const [command, ...argumentsList] = process.argv.slice(2);
